"use client";
import "./styles/skeuo-photo-carousel.css";

import { useEffect, useLayoutEffect, useId, useRef, useState, type CSSProperties, type PointerEvent } from "react";
export type PhotoCarouselItem = { id: string; image: string; imageAlt: string; title: string; label: string; meta?: string; eyebrow?: string; subtitle?: string; description?: string; photoPosition?: string };
export function SkeuoPhotoCarousel({ items, label = "Photo collection", autoPlay = true }: { items: PhotoCarouselItem[]; label?: string; autoPlay?: boolean }) {
  if (!items.length) return <p>No photographs yet.</p>;
  return <CarouselContent key={items.map(item => item.id).join("|")} items={items} label={label} autoPlay={autoPlay} />;
}
function PhotoRecord({ item, onClose }: { item: PhotoCarouselItem; onClose: () => void }) {
  const dialog = useRef<HTMLDialogElement>(null);
  const closing = useRef(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const title = useId();
  useEffect(() => {
    const node = dialog.current;
    if (!node) return;
    const previous = document.body.style.overflow;
    const previousPadding = document.body.style.paddingRight;
    const scrollbar = window.innerWidth - document.documentElement.clientWidth;
    if (scrollbar > 0) document.body.style.paddingRight = `${parseFloat(getComputedStyle(document.body).paddingRight) + scrollbar}px`;
    document.body.style.overflow = "hidden";
    node.showModal();
    // Establish the starting frame before moving into the open pose.
    node.getBoundingClientRect();
    const frame = requestAnimationFrame(() => { node.dataset.phase = "open"; });
    return () => {
      cancelAnimationFrame(frame);
      if (closeTimer.current) clearTimeout(closeTimer.current);
      node.close();
      document.body.style.overflow = previous;
      document.body.style.paddingRight = previousPadding;
    };
  }, []);
  function dismiss() {
    if (closing.current) return;
    closing.current = true;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { onClose(); return; }
    if (dialog.current) dialog.current.dataset.phase = "closing";
    closeTimer.current = setTimeout(onClose, 450);
  }
  return <dialog data-sk-root="" ref={dialog} className="sk-photo-record" aria-labelledby={title} onCancel={event => { event.preventDefault(); dismiss(); }} onClick={event => { if(event.target === event.currentTarget) { const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left || event.clientX>r.right || event.clientY<r.top || event.clientY>r.bottom) dismiss(); } }}><header><h3 id={title}>{item.title}</h3><button autoFocus type="button" className="sk-album-more" onClick={dismiss}>Close ×</button></header><div className="sk-photo-record-image"><img src={item.image} alt={item.imageAlt} /></div><p>{item.description ?? item.subtitle}</p></dialog>;
}
function CarouselContent({ items: achievements, label, autoPlay }: { items: PhotoCarouselItem[]; label: string; autoPlay: boolean }) {
  const headingId = useId();
  const [active, setActive] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const root = useRef<HTMLElement>(null);
  const finishReveal = useRef<() => void>(() => {});
  const hovered = useRef(false);
  const focused = useRef(false);
  const readingUntil = useRef(0);
  const restart = useRef<() => void>(() => {});
  const opener = useRef<HTMLButtonElement | null>(null);
  const swipe = useRef<{ x: number; y: number; pointer: number } | null>(null);
  const suppressClick = useRef(false);
  const resetClickTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const award = achievements[active % achievements.length];
  // Reuse the portfolio’s centered stack-to-fan reveal when it enters view.
  useLayoutEffect(() => {
    const stage = root.current?.querySelector<HTMLElement>(".sk-album-stage");
    if (!stage) return;
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (motion.matches) return;
    const animations: Animation[] = [];
    let revealed = false;
    const finish = () => {
      revealed = true;
      delete stage.dataset.reveal;
      animations.forEach(animation => animation.cancel());
      observer.disconnect();
    };
    const observer = new IntersectionObserver(entries => {
      if (revealed || !entries.some(entry => entry.isIntersecting)) return;
      revealed = true;
      delete stage.dataset.reveal;
      const cards = Array.from(stage.querySelectorAll<HTMLElement>(".sk-album-print"));
      cards.forEach((card,index) => {
        const final = getComputedStyle(card).transform;
        animations.push(card.animate([
          { transform:"translate(-50%, -46%) rotate(0deg) scale(.84)",opacity:0 },
          { transform:final,opacity:1 },
        ], { duration:1100,delay:index * 65,easing:"cubic-bezier(.22,.65,.3,1)",fill:"both" }));
      });
      Promise.all(animations.map(animation => animation.finished)).then(finish).catch(() => {});
      observer.disconnect();
    }, {threshold:.2,rootMargin:"0px 0px -35px 0px"});
    stage.dataset.reveal = "pending";
    finishReveal.current = finish;
    observer.observe(stage);
    motion.addEventListener("change",finish);
    return () => {finish();motion.removeEventListener("change",finish);finishReveal.current = () => {};};
  }, []);

  useEffect(() => () => { if (resetClickTimer.current) clearTimeout(resetClickTimer.current); }, []);

  useEffect(() => {
    const section = root.current;
    if (!section) return;
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let visible = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    function schedule() {
      clearTimeout(timer);
      if (selected !== null || hovered.current || focused.current || document.hidden || motion.matches || !visible || !autoPlay) return;
      timer = setTimeout(() => {
        setActive(index => (index + 1) % achievements.length);
        schedule();
      }, Math.max(4000, readingUntil.current - performance.now()));
    }
    restart.current = schedule;
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      schedule();
    }, { threshold: 0.25 });
    observer.observe(section);
    document.addEventListener("visibilitychange", schedule);
    motion.addEventListener("change", schedule);
    return () => {
      clearTimeout(timer);
      observer.disconnect();
      document.removeEventListener("visibilitychange", schedule);
      motion.removeEventListener("change", schedule);
      restart.current = () => {};
    };
  }, [selected, achievements.length, autoPlay]);

  function reading(timestamp: number, delay = 12000) {
    readingUntil.current = Math.max(readingUntil.current, timestamp + delay);
    restart.current();
  }

  function move(step: number) { setActive(index => (index + step + achievements.length) % achievements.length); }
  function showRecord(button: HTMLButtonElement) { opener.current = button; setSelected(active); }
  function endSwipe(event: PointerEvent<HTMLDivElement>) {
    const start = swipe.current;
    swipe.current = null;
    if (!start || start.pointer !== event.pointerId) return;
    const dx = event.clientX - start.x, dy = event.clientY - start.y;
    if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy) * 1.2) return;
    suppressClick.current = true;
    move(dx > 0 ? -1 : 1);
    resetClickTimer.current = setTimeout(() => { suppressClick.current = false; }, 0);
  }

  return <section data-sk-root="" ref={root} className="sk-photo-carousel" aria-labelledby={headingId}
    onPointerEnter={event => { if (event.pointerType !== "touch") { hovered.current = true; restart.current(); } }}
    onPointerLeave={event => { hovered.current = false; reading(event.timeStamp, 8000); }}
    onPointerDownCapture={event => { finishReveal.current(); reading(event.timeStamp, event.pointerType === "touch" ? 20000 : 12000); }}
    onKeyDownCapture={event => { finishReveal.current(); reading(event.timeStamp); }}
    onFocusCapture={() => { focused.current = true; restart.current(); }}
    onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) { focused.current = false; reading(event.timeStamp, 8000); } }}>
    <div className="sk-album-heading"><h2 id={headingId}>{label}</h2><span className="sk-album-count">{String(active + 1).padStart(2,"0")} / {String(achievements.length).padStart(2,"0")}</span></div>
    <div className="sk-album" role="region" aria-roledescription="carousel" aria-label="Photo collection" tabIndex={0} onKeyDown={event => { if (selected !== null) return; if (event.key === "ArrowLeft" || event.key === "ArrowRight") { event.preventDefault(); move(event.key === "ArrowLeft" ? -1 : 1); } }}>
      <div className="sk-album-stage" onPointerDown={event => { if (event.button === 0) swipe.current = { x: event.clientX, y: event.clientY, pointer: event.pointerId }; }} onPointerUp={endSwipe} onPointerCancel={() => { swipe.current = null; }}>
        {achievements.map((item, index) => {
          let offset = (index - active + achievements.length) % achievements.length;
          if (offset > achievements.length / 2) offset -= achievements.length;
          const distance = Math.abs(offset);
          const style = { "--sk-album-offset": `${offset * (distance === 1 ? 26 : 21)}%`, "--sk-album-offset-mobile": `${offset * (distance === 1 ? 12 : 7)}%`, "--sk-album-rotation": `${offset === 0 ? -1.5 : offset * 6}deg`, "--sk-album-scale": 1 - distance * .1, zIndex: achievements.length - distance, visibility: distance > 2 ? "hidden" : "visible" } as CSSProperties;
          return <button data-sk-root="" key={item.id} type="button" className="sk-album-print" data-active={offset === 0} style={style} tabIndex={offset === 0 ? 0 : -1} aria-label={offset === 0 ? `View ${item.title} photo details` : `Bring ${item.title} photo forward`} aria-haspopup={offset === 0 ? "dialog" : undefined} onClick={event => { if (suppressClick.current) return; if (index === active) showRecord(event.currentTarget); else setActive(index); }}>
            <span className="sk-album-image"><img src={item.image} alt={item.imageAlt} draggable={false} loading="lazy" style={{ objectPosition: item.photoPosition ?? "center" }} /></span>
            <span className="sk-album-print-footer"><span>{item.label}</span><span>{item.meta}</span></span>
          </button>;
        })}
      </div>
      <div className="sk-album-caption">
        <div key={award.id} className="sk-album-caption-copy" aria-live="off" aria-atomic="true"><p className="sk-album-eyebrow">{award.eyebrow ?? "Photo journal"}</p><h3 className="sk-album-title">{award.title}</h3><p className="sk-album-subtitle">{award.subtitle}</p></div>
        <button type="button" className="sk-album-more" aria-haspopup="dialog" aria-label={`More info about ${award.title}`} onClick={event => showRecord(event.currentTarget)}>More info <span aria-hidden="true">↗</span></button>
      </div>
      <div className="sk-album-controls">
        <button type="button" className="sk-album-arrow" aria-label="Previous photo" onClick={() => move(-1)}><svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden="true"><path d="m11 5-5 5 5 5M6 10h10" /></svg></button>
        <div className="sk-album-index" aria-label="Choose a photo">{achievements.map((item, index) => <button key={item.id} type="button" aria-label={`Show ${item.title}`} aria-current={active === index ? "true" : undefined} onClick={() => setActive(index)}><span /></button>)}</div>
        <button type="button" className="sk-album-arrow" aria-label="Next photo" onClick={() => move(1)}><svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden="true"><path d="m9 5 5 5-5 5M14 10H4" /></svg></button>
      </div>
    </div>
    {selected !== null && <PhotoRecord item={achievements[selected]} onClose={() => { setSelected(null); requestAnimationFrame(() => opener.current?.focus({ preventScroll: true })); }} />}
  </section>;
}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

@import "./skeuo-base.css";
.sk-album-stage { position: relative; height: clamp(330px, 54vw, 455px); touch-action: pan-y; perspective: 1500px; }
.sk-album-print {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 70%;
  padding: 11px 11px 0;
  border: 1px solid var(--sk-album-edge);
  border-radius: 5px;
  background: var(--sk-album-paper);
  color: var(--sk-album-ink);
  box-shadow: inset 0 1px 0 var(--sk-highlight), inset 0 -2px 0 var(--sk-album-base), 0 3px 0 var(--sk-album-base), 0 4px 0 var(--sk-album-edge), 0 14px 22px #00000038;
  transform: translate(calc(-50% + var(--sk-album-offset)), -50%) rotate(var(--sk-album-rotation)) scale(var(--sk-album-scale));
  transform-origin: 50% 70%;
  transition: transform 650ms cubic-bezier(.22,.65,.3,1), box-shadow 500ms ease;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
}
.sk-album-print[data-active="true"] { box-shadow: inset 0 1px 0 var(--sk-highlight), inset 0 -2px 0 var(--sk-album-base), 0 3px 0 var(--sk-album-base), 0 4px 0 var(--sk-album-edge), 0 24px 34px #00000055; }
.sk-album-image { position: relative; display: block; aspect-ratio: 4 / 3; overflow: hidden; border: 1px solid var(--sk-album-edge); border-bottom-color: var(--sk-highlight); border-radius: 2px; background: var(--sk-well); }
.sk-album-image img { object-fit: cover; pointer-events: none; }
.sk-album-image[data-certificate="true"] { background: white; }
.sk-album-image[data-certificate="true"] img { object-fit: contain; }
.sk-album-image::after { content: ""; position: absolute; inset: 0; pointer-events: none; box-shadow: inset 0 4px 7px #00000055, inset 0 -1px 0 #ffffff20; }
.sk-album-print-footer { display: flex; justify-content: space-between; gap: 12px; padding: 13px 4px 15px; font: 10px/1.5 var(--sk-font-mono), monospace; }
.sk-album-print[data-active="true"] .sk-album-print-footer > :first-child { color: var(--sk-accent); }
.sk-album-caption { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 15px 7px 0; }
.sk-album-caption-copy { animation: sk-album-caption 380ms ease both; }
@keyframes sk-album-caption { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
.sk-album-more { display: inline-flex; flex-shrink: 0; justify-content: center; align-items: center; gap: 10px; min-height: 38px; padding: 9px 12px; border: 1px solid var(--sk-key-edge); border-radius: 5px; background: var(--sk-key); color: var(--sk-ink); box-shadow: inset 0 1px 0 var(--sk-highlight), inset 0 -1px 0 var(--sk-key-base), 0 2px 0 var(--sk-key-base), 0 3px 0 var(--sk-key-edge); font: 10px/1.5 var(--sk-font-mono), monospace; cursor: pointer; transition: transform .15s, box-shadow .15s; }
.sk-album-more:active { transform: translateY(2px); box-shadow: inset 0 2px 3px var(--sk-shadow), 0 1px 0 var(--sk-key-edge); }
.sk-album-controls { display: flex; align-items: center; justify-content: center; gap: 17px; margin-top: 25px; }
.sk-album-arrow { display: grid; place-items: center; width: 35px; height: 35px; border: 1px solid var(--sk-key-edge); border-radius: 50%; background: var(--sk-key); color: var(--sk-ink); box-shadow: inset 0 1px 0 var(--sk-highlight), 0 2px 0 var(--sk-key-base), 0 3px 0 var(--sk-key-edge); cursor: pointer; }
.sk-album-arrow:active { transform: translateY(2px); box-shadow: inset 0 2px 3px var(--sk-shadow); }
.sk-album-index { display: flex; gap: 2px; }
.sk-album-index button { display: grid; place-items: center; width: 27px; height: 35px; cursor: pointer; border: 0; background: transparent; transition: width .4s ease; }
.sk-album-index button span { width: 7px; height: 7px; border-radius: 999px; background: var(--sk-key-edge); box-shadow: inset 0 1px 2px var(--sk-shadow), 0 1px 0 var(--sk-highlight); transition: background-color .35s, width .4s cubic-bezier(.22,.65,.3,1); }
.sk-album-index button[aria-current="true"] { width: 43px; }
.sk-album-index button[aria-current="true"] span { width: 26px; background: var(--sk-accent); }

.sk-photo-carousel {width:100%;max-width:520px;margin-inline:auto;min-width:0;container:sk-photo-album / inline-size;}
.sk-album-heading {display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px;}
.sk-album-heading h2 {font-size:17px;font-weight:500;letter-spacing:-.5px;}
.sk-album-count {font:10px var(--sk-font-mono),monospace;color:var(--sk-muted);}
.sk-album-stage {height:auto;aspect-ratio:1.4;overflow:visible;}
.sk-album-image img {position:absolute;inset:0;width:100%;height:100%;}
.sk-album-title {font-size:18px;font-weight:500;margin:7px 0;letter-spacing:-.5px;}
.sk-album-eyebrow {color:var(--sk-accent);font:10px var(--sk-font-mono),monospace;}
.sk-album-subtitle {color:var(--sk-muted);font-size:11px;line-height:1.7;margin:0;}
.sk-photo-record {width:min(620px,calc(100vw - 32px));max-height:calc(100svh - 40px);overflow:auto;margin:auto;padding:22px;border:1px solid var(--sk-edge);border-radius:12px;background:var(--sk-surface-raised);color:var(--sk-ink);box-shadow:inset 0 1px var(--sk-highlight),0 5px var(--sk-base),0 6px var(--sk-edge),0 30px 70px #00000070;}
.sk-photo-record::backdrop {background:#000000a0;backdrop-filter:blur(4px);}
.sk-photo-record header {display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px;}
.sk-photo-record h3 {font-size:19px;font-weight:500;margin:0;}
.sk-photo-record-image {border:6px solid var(--sk-base);border-radius:4px;box-shadow:inset 0 3px 5px var(--sk-shadow);}
.sk-photo-record img {display:block;width:100%;max-height:55svh;object-fit:contain;}
.sk-photo-record p {font-size:13px;color:var(--sk-muted);line-height:1.8;margin-top:20px;}
@container sk-photo-album (max-width:440px) {
 .sk-album-stage {aspect-ratio:1.12;}
 .sk-album-print {width:80%;padding:7px 7px 0;transform:translate(calc(-50% + var(--sk-album-offset-mobile)),-50%) rotate(var(--sk-album-rotation)) scale(var(--sk-album-scale));}
 .sk-album-print-footer {padding:10px 2px 12px;font-size:8px;}
 .sk-album-caption {padding:10px 0 0;gap:10px;}
 .sk-album-title {font-size:16px;}.sk-album-more {font-size:9px;padding:8px;}
 .sk-album-controls {gap:8px;margin-top:18px;}.sk-album-index button {width:21px;}.sk-album-index button[aria-current="true"] {width:32px;}
}
@media(prefers-reduced-motion:reduce) {.sk-photo-carousel * {animation:none !important;transition:none !important;}}

.sk-photo-carousel .sk-album-heading h2 {font-size:17px;margin:0;font-weight:500;}

.sk-album-stage[data-reveal="pending"] .sk-album-print {opacity:0;}
@media(prefers-reduced-motion:reduce) {.sk-album-stage[data-reveal="pending"] .sk-album-print {opacity:1;}}

/* The printed record settles into place, followed by its photograph and notes. */
.sk-photo-record {opacity:0;transform:translateY(28px) scale(.955);transform-origin:50% 60%;transition:opacity 650ms ease,transform 850ms cubic-bezier(.18,.72,.22,1);}
.sk-photo-record[data-phase="open"] {opacity:1;transform:translateY(0) scale(1);}
.sk-photo-record::backdrop {background:#00000000;backdrop-filter:blur(0);transition:background-color 650ms ease,backdrop-filter 850ms ease;}
.sk-photo-record[data-phase="open"]::backdrop {background:#000000a0;backdrop-filter:blur(4px);}
.sk-photo-record > header,.sk-photo-record-image,.sk-photo-record > p {opacity:0;transform:translateY(9px);transition:opacity 600ms ease,transform 750ms cubic-bezier(.18,.72,.22,1);}
.sk-photo-record[data-phase="open"] > header,.sk-photo-record[data-phase="open"] .sk-photo-record-image,.sk-photo-record[data-phase="open"] > p {opacity:1;transform:translateY(0);}
.sk-photo-record[data-phase="open"] > header {transition-delay:90ms;}
.sk-photo-record[data-phase="open"] .sk-photo-record-image {transition-delay:150ms;}
.sk-photo-record[data-phase="open"] > p {transition-delay:220ms;}
.sk-photo-record[data-phase="closing"] {opacity:0;transform:translateY(16px) scale(.975);transition-duration:400ms;}
.sk-photo-record[data-phase="closing"]::backdrop {transition-duration:400ms;}
.sk-photo-record[data-phase="closing"] > * {transition-duration:250ms;transition-delay:0ms;}
@media(prefers-reduced-motion:reduce) {.sk-photo-record,.sk-photo-record::backdrop,.sk-photo-record > * {transition:none !important;transform:none !important;}.sk-photo-record[data-phase="open"] > * {opacity:1;}}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
